const ASSETS={"/":{"body":"<!doctype html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <meta name=\"description\" content=\"Consulta inicial gratuita y acompañamiento frente a barreras del sistema de salud colombiano.\">\n  <meta name=\"theme-color\" content=\"#0B3A53\">\n  <title>Salvación M — Tu salud, nuestros derechos</title>\n  <link rel=\"icon\" href=\"favicon.svg\" type=\"image/svg+xml\">\n  <script src=\"intro.js?v=1\"></script>\n  <link rel=\"stylesheet\" href=\"styles.css?v=12\">\n  <style>.lead-form{display:grid;gap:14px;margin-top:22px}.lead-form label{display:grid;gap:6px;font-weight:700}.lead-form input,.lead-form textarea{width:100%;box-sizing:border-box;border:1px solid #8faeb8;border-radius:9px;padding:12px;font:inherit}.lead-form textarea{min-height:84px}.lead-form .consent{display:flex;gap:9px;align-items:flex-start;font-weight:400}.lead-form .consent input{width:auto;margin-top:4px}.form-status{padding:12px;border-radius:9px;background:#edf7f4}.form-status.error{background:#fff0ed;color:#842b20}.reference{font-size:1.35rem;color:#0b3a53;font-weight:800}</style>\n</head>\n<body>\n  <a class=\"skip\" href=\"#main\">Ir al contenido</a>\n  <header class=\"topbar\">\n    <a class=\"brand brand-motion\" href=\"#inicio\" aria-label=\"Salvación M, inicio; pulsa para reproducir la animación\">\n      <svg viewBox=\"0 0 430 96\" role=\"img\" aria-labelledby=\"header-logo-title header-logo-desc\">\n        <title id=\"header-logo-title\">Salvación M</title>\n        <desc id=\"header-logo-desc\">Dos figuras humanas curvas forman una M de acompañamiento y protección.</desc>\n        <g aria-hidden=\"true\">\n          <g class=\"person-left\"><circle cx=\"29\" cy=\"17\" r=\"10\" fill=\"#0B3A53\"/><path d=\"M14 82V36c0-10 10-16 18-9l32 30v16c-2 2-4 2-5 0L30 46v7c0 13-6 23-16 29Z\" fill=\"#0B3A53\"/></g>\n          <g class=\"person-right\"><circle cx=\"99\" cy=\"17\" r=\"10\" fill=\"#008C8C\"/><path d=\"M114 82V36c0-10-10-16-18-9L64 57v16c2 2 4 2 5 0l29-27v7c0 13 6 23 16 29Z\" fill=\"#1F8A5B\"/></g>\n          <path class=\"embrace-line\" d=\"M26 36c9 3 17 10 24 17 5 5 10 9 14 9s9-4 14-9c7-7 15-14 24-17\" fill=\"none\" stroke=\"#fff\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n        </g>\n        <g class=\"wordmark\"><text x=\"134\" y=\"50\" fill=\"#0B3A53\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"28\" font-weight=\"800\" letter-spacing=\"2\">SALVACIÓN <tspan fill=\"#1F8A5B\">M</tspan></text><text x=\"135\" y=\"72\" fill=\"#53666F\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"11.5\" font-weight=\"600\" letter-spacing=\".35\">ORIENTACIÓN Y ACOMPAÑAMIENTO EN SALUD</text></g>\n      </svg>\n    </a>\n    <button class=\"menu\" aria-expanded=\"false\" aria-controls=\"nav\">Menú</button>\n    <nav id=\"nav\" aria-label=\"Principal\">\n      <a href=\"#problemas\">Problemas frecuentes</a><a href=\"#como\">Cómo ayudamos</a><a href=\"#recursos\">Recursos</a><a href=\"#nosotros\">Nosotros</a>\n      <a class=\"nav-cta\" href=\"#orientador\">Cuéntanos tu caso</a>\n    </nav>\n  </header>\n\n  <main id=\"main\">\n    <section class=\"hero\" id=\"inicio\">\n      <div class=\"hero-copy\">\n        <p class=\"eyebrow\">Orientación clara para actuar</p>\n        <h1 data-hero-title>Tu salud,<br><span>nuestros derechos.</span></h1>\n        <p class=\"lead\">Si una EPS, IPS o farmacia está demorando o negando un servicio, empieza por contar qué está pasando. La consulta inicial es gratuita; después se informa el alcance y el precio de cualquier servicio adicional.</p>\n        <div class=\"actions\"><a class=\"button primary\" href=\"#orientador\">Cuéntanos tu caso</a><a class=\"button ghost\" href=\"#como\">Cómo podemos ayudarte</a></div>\n        <p class=\"fine\">Salvación M es un servicio independiente de orientación. No somos EPS, IPS, clínica, autoridad pública ni servicio de urgencias.</p>\n      </div>\n      <aside class=\"route-card\" aria-label=\"Ruta de orientación\">\n        <p class=\"step-label\">TU RUTA</p>\n        <ol><li><b>Cuéntanos el problema</b><span>En palabras sencillas.</span></li><li><b>Ordenamos la información</b><span>Fechas, respuestas y documentos.</span></li><li><b>Identificamos opciones</b><span>Pasos claros y límites.</span></li></ol>\n      </aside>\n    </section>\n\n    <section class=\"section\" id=\"problemas\">\n      <div class=\"section-head\"><p class=\"eyebrow\">Empieza por tu situación</p><h2>¿Qué problema tienes?</h2><p>Elige la opción que más se parece a lo que ocurre. No necesitas conocer el nombre del trámite.</p></div>\n      <aside class=\"urgent-check\" aria-labelledby=\"urgent-title\">\n        <div class=\"urgent-check-icon\" aria-hidden=\"true\">!</div>\n        <div class=\"urgent-check-copy\"><p class=\"eyebrow\">Primero, lo importante</p><h3 id=\"urgent-title\">¿Tu situación requiere atención inmediata?</h3><p>Si hay riesgo para la vida o la integridad, busca atención de urgencias. No esperes una orientación digital.</p></div>\n        <div class=\"urgent-check-actions\"><a class=\"button urgent-action\" href=\"#orientador\" data-urgent-choice=\"yes\">Sí, es urgente</a><a class=\"button urgent-secondary\" href=\"#orientador\" data-urgent-choice=\"unknown\">No estoy seguro</a></div>\n      </aside>\n      <p class=\"problem-prompt\">Si no es una urgencia, selecciona la situación principal:</p>\n      <div class=\"problem-grid\">\n        <button class=\"problem\" data-problem=\"medicamento\"><span class=\"problem-icon\" aria-hidden=\"true\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#008c8c\" stroke-width=\"1.9\"><path d=\"M8.2 5.2a4.2 4.2 0 0 1 5.9 0l4.7 4.7a4.2 4.2 0 0 1-5.9 5.9l-4.7-4.7a4.2 4.2 0 0 1 0-5.9Z\"/><path d=\"m10.3 7.3 6.4 6.4M6.5 17.5h5M9 15v5\"/></svg></span><b>No me entregan un medicamento</b><small>Hay orden médica, pero la entrega no ocurre.</small><i aria-hidden=\"true\">Elegir</i></button>\n        <button class=\"problem\" data-problem=\"procedimiento\"><span class=\"problem-icon\" aria-hidden=\"true\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#008c8c\" stroke-width=\"1.9\"><path d=\"M12 20a8 8 0 1 0 0-16 8 8 0 0 0 0 16Z\"/><path d=\"m8.5 12 2.3 2.3 4.7-4.7\"/></svg></span><b>No autorizan mi procedimiento</b><small>La autorización está negada o demorada.</small><i aria-hidden=\"true\">Elegir</i></button>\n        <button class=\"problem\" data-problem=\"especialista\"><span class=\"problem-icon\" aria-hidden=\"true\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#008c8c\" stroke-width=\"1.9\"><circle cx=\"12\" cy=\"8\" r=\"3\"/><path d=\"M5.5 20c.5-3.2 2.7-5 6.5-5s6 1.8 6.5 5M18.5 5.5h3M20 4v3\"/></svg></span><b>No consigo cita o especialista</b><small>No hay agenda o la espera se prolonga.</small><i aria-hidden=\"true\">Elegir</i></button>\n        <button class=\"problem\" data-problem=\"continuidad\"><span class=\"problem-icon\" aria-hidden=\"true\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#008c8c\" stroke-width=\"1.9\"><path d=\"M7 7h8.5M15.5 7 18 9.5 15.5 12M17 17H8.5M8.5 17 6 14.5 8.5 12\"/><path d=\"M18 9.5a7 7 0 0 1-1 7.5M6 14.5a7 7 0 0 1 1-7.5\"/></svg></span><b>Interrumpieron mi tratamiento</b><small>Un tratamiento en curso dejó de prestarse.</small><i aria-hidden=\"true\">Elegir</i></button>\n        <button class=\"problem\" data-problem=\"negacion\"><span class=\"problem-icon\" aria-hidden=\"true\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#008c8c\" stroke-width=\"1.9\"><circle cx=\"12\" cy=\"12\" r=\"8\"/><path d=\"m8.5 8.5 7 7M15.5 8.5l-7 7\"/></svg></span><b>Me negaron un servicio</b><small>Recibiste una negativa verbal o escrita.</small><i aria-hidden=\"true\">Elegir</i></button>\n      </div>\n    </section>\n\n    <section class=\"orientador-wrap\" id=\"orientador\">\n      <div class=\"orientador-intro\"><p class=\"eyebrow light\">Consulta inicial gratuita</p><h2>Cuéntanos tu caso</h2><p>Responde cinco preguntas y recibe una ruta inicial. Si decides solicitar revisión, completa tus datos y, si deseas, indica una fecha preferida.</p><div class=\"privacy-note\">No incluyas diagnósticos ni historia clínica. Solo guardaremos los datos cuando autorices y envíes la solicitud.</div></div>\n      <form id=\"caseForm\" class=\"wizard\" novalidate>\n        <input type=\"hidden\" name=\"entity\" value=\"por_confirmar\"><input type=\"hidden\" name=\"order\" value=\"por_confirmar\"><input type=\"hidden\" name=\"action\" value=\"orientacion_inicial\">\n        <div class=\"progress\"><span id=\"progressText\">Paso 1 de 5</span><progress id=\"progress\" value=\"1\" max=\"5\">20%</progress></div>\n        <fieldset class=\"panel active\" data-step=\"1\"><legend>¿Cuál es el problema principal?</legend>\n          <div class=\"choices\">\n            <label><input type=\"radio\" name=\"problem\" value=\"medicamento\" required><span>No entregan un medicamento</span></label>\n            <label><input type=\"radio\" name=\"problem\" value=\"procedimiento\"><span>No autorizan un procedimiento</span></label>\n            <label><input type=\"radio\" name=\"problem\" value=\"especialista\"><span>No asignan cita o especialista</span></label>\n            <label><input type=\"radio\" name=\"problem\" value=\"continuidad\"><span>Interrumpieron un tratamiento</span></label>\n            <label><input type=\"radio\" name=\"problem\" value=\"negacion\"><span>Negaron un servicio</span></label>\n          </div>\n        </fieldset>\n        <fieldset class=\"panel\" data-step=\"2\"><legend>¿Existe un riesgo inmediato?</legend><p class=\"help\">Por ejemplo: dificultad grave para respirar, pérdida de conciencia o riesgo evidente para la vida.</p>\n          <div class=\"choices\"><label><input type=\"radio\" name=\"urgent\" value=\"yes\" required><span>Sí, puede ser una emergencia</span></label><label><input type=\"radio\" name=\"urgent\" value=\"no\"><span>No identifico un riesgo inmediato</span></label><label><input type=\"radio\" name=\"urgent\" value=\"unknown\"><span>No estoy seguro</span></label></div>\n        </fieldset>\n        <fieldset class=\"panel\" data-step=\"3\"><legend>¿Quién está poniendo la barrera?</legend><p class=\"help\">Elige la entidad que te dio la respuesta o donde ocurrió la dificultad.</p><div class=\"choices\"><label><input type=\"radio\" name=\"entity_choice\" value=\"eps\" required><span>Mi EPS</span></label><label><input type=\"radio\" name=\"entity_choice\" value=\"ips\"><span>Una IPS, clínica u hospital</span></label><label><input type=\"radio\" name=\"entity_choice\" value=\"pharmacy\"><span>Una farmacia o proveedor</span></label><label><input type=\"radio\" name=\"entity_choice\" value=\"unknown\"><span>No estoy seguro</span></label></div></fieldset>\n        <fieldset class=\"panel\" data-step=\"4\"><legend>¿Qué soporte tienes?</legend><div class=\"choices\"><label><input type=\"radio\" name=\"support\" value=\"written\" required><span>Respuesta o negación escrita</span></label><label><input type=\"radio\" name=\"support\" value=\"order\"><span>Orden o fórmula médica</span></label><label><input type=\"radio\" name=\"support\" value=\"verbal\"><span>Respuesta verbal</span></label><label><input type=\"radio\" name=\"support\" value=\"none\"><span>Aún no tengo soporte</span></label></div></fieldset>\n        <fieldset class=\"panel\" data-step=\"5\"><legend>¿Hace cuánto ocurre?</legend><div class=\"choices\"><label><input type=\"radio\" name=\"time\" value=\"today\" required><span>Hoy o ayer</span></label><label><input type=\"radio\" name=\"time\" value=\"week\"><span>Entre 3 y 7 días</span></label><label><input type=\"radio\" name=\"time\" value=\"month\"><span>Más de una semana</span></label><label><input type=\"radio\" name=\"time\" value=\"unknown\"><span>No lo sé</span></label></div></fieldset>\n        <p id=\"formError\" class=\"error\" role=\"alert\"></p>\n        <div class=\"wizard-actions\"><button type=\"button\" id=\"prev\" class=\"button ghost\" hidden>Anterior</button><button type=\"button\" id=\"next\" class=\"button primary\">Continuar</button><button type=\"submit\" id=\"finish\" class=\"button primary\" hidden>Ver orientación</button></div>\n      </form>\n      <div id=\"result\" class=\"result\" hidden tabindex=\"-1\"></div>\n    </section>\n\n    <section class=\"section split\" id=\"como\"><div><p class=\"eyebrow\">Un servicio delimitado</p><h2>Te ayudamos a entender, ordenar y actuar</h2></div><div class=\"service-list\"><article><b>Orientación inicial</b><p>Identificamos información faltante, entidad involucrada y ruta posible.</p></article><article><b>Revisión del caso</b><p>Analizamos documentos y respuestas dentro del alcance contratado.</p></article><article><b>Acompañamiento</b><p>Preparamos contigo el siguiente paso, sin garantizar decisiones de terceros.</p></article></div></section>\n\n    <section class=\"section resources\" id=\"recursos\"><div class=\"section-head\"><p class=\"eyebrow\">Para tomar decisiones informadas</p><h2>Recursos esenciales</h2></div><div class=\"resource-grid\"><article><span>Guía</span><h3>Cómo organizar un caso</h3><p>Una cronología simple puede mostrar qué ocurrió, cuándo y quién respondió.</p></article><article><span>Lista</span><h3>Documentos útiles</h3><p>Orden médica, autorización, respuesta, radicado y evidencia de seguimiento.</p></article><article><span>Directorio</span><h3>Canales institucionales</h3><p>Identifica el canal oficial antes de compartir información sensible.</p></article></div></section>\n\n    <section class=\"section about\" id=\"nosotros\"><div><p class=\"eyebrow light\">Salvación M</p><h2>Humanidad para escuchar.<br>Rigor para orientar.</h2></div><p>Responsable: Daniel Enrique Vergel González Rubio, abogado, C.C. 72.255.284. La consulta inicial es gratuita. Si el caso requiere un servicio adicional, su alcance y precio se informan antes de contratar. No ofrecemos pagos en línea.</p></section>\n\n    <section class=\"section\" id=\"privacidad\"><div class=\"section-head\"><p class=\"eyebrow\">Transparencia</p><h2>Política de privacidad</h2></div><div><p><b>Responsable:</b> Daniel Enrique Vergel González Rubio, C.C. 72.255.284. Contacto: <a href=\"mailto:devergel@yahoo.com\">devergel@yahoo.com</a> y WhatsApp <a href=\"https://wa.me/573012370047\">301 237 0047</a>.</p><p>Los datos suministrados voluntariamente se tratarán para responder consultas, evaluar casos, gestionar citas, prestar servicios contratados, comunicarnos, conservar constancias y cumplir obligaciones legales. Los datos de salud son sensibles: no deben enviarse mediante este formulario; si posteriormente fueran indispensables, se solicitará autorización explícita.</p><p>El titular puede conocer, actualizar, rectificar y solicitar supresión; pedir prueba de autorización; conocer el uso; presentar quejas ante la autoridad competente; y revocar la autorización cuando legalmente proceda.</p><p>Aplicamos minimización, acceso restringido, confidencialidad y conservación limitada. No vendemos datos. Las respuestas solo se almacenan cuando el titular envía voluntariamente la solicitud; el consentimiento queda asociado a su referencia.</p><p><b>Vigencia:</b> 21 de septiembre de 2026. Política elaborada bajo la Ley 1581 de 2012 y sus normas reglamentarias aplicables.</p></div></section>\n\n    <section class=\"section split\" id=\"terminos\"><div><p class=\"eyebrow\">Condiciones del servicio</p><h2>Términos de consulta y contratación</h2></div><div><p>La consulta inicial es gratuita y no crea por sí sola mandato, representación judicial ni obligación de aceptar el caso.</p><p>Si se propone un servicio adicional, antes de contratar se informarán por escrito objeto, alcance, exclusiones, honorarios, forma de pago, duración estimada y terminación. No existe pasarela de pago en este sitio.</p><p>Salvación M no presta atención médica, no sustituye urgencias ni garantiza decisiones administrativas o judiciales. La contratación se perfecciona mediante aceptación expresa de la propuesta correspondiente.</p></div></section>\n\n    <section class=\"cta\"><p class=\"eyebrow\">Tu siguiente paso puede ser más claro</p><h2>Empieza por contarnos qué está pasando.</h2><a class=\"button primary\" href=\"#orientador\">Iniciar orientación</a></section>\n  </main>\n\n  <footer><div class=\"brand inverse\"><img src=\"logo-salvacion-m-inverse.svg\" alt=\"Salvación M — Tu salud, nuestros derechos\" width=\"430\" height=\"96\"></div><div><b>Información</b><a href=\"#como\">Alcance</a><a href=\"#privacidad\">Privacidad</a><a href=\"#terminos\">Términos</a><a href=\"mailto:devergel@yahoo.com\">devergel@yahoo.com</a><a href=\"https://wa.me/573012370047\">WhatsApp 301 237 0047</a></div><div><b>Importante</b><p>No prestamos atención médica ni sustituimos servicios de urgencias. Ante una emergencia, acude a los canales oficiales de atención.</p></div><p class=\"copyright\">© 2026 Salvación M · Daniel Enrique Vergel González Rubio, abogado · C.C. 72.255.284</p></footer>\n  <script src=\"app.js?v=12\"></script>\n  <script src=\"contact.js?v=1\"></script>\n</body></html>\n","type":"text/html; charset=utf-8"},"/index.html":{"body":"<!doctype html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <meta name=\"description\" content=\"Consulta inicial gratuita y acompañamiento frente a barreras del sistema de salud colombiano.\">\n  <meta name=\"theme-color\" content=\"#0B3A53\">\n  <title>Salvación M — Tu salud, nuestros derechos</title>\n  <link rel=\"icon\" href=\"favicon.svg\" type=\"image/svg+xml\">\n  <script src=\"intro.js?v=1\"></script>\n  <link rel=\"stylesheet\" href=\"styles.css?v=12\">\n  <style>.lead-form{display:grid;gap:14px;margin-top:22px}.lead-form label{display:grid;gap:6px;font-weight:700}.lead-form input,.lead-form textarea{width:100%;box-sizing:border-box;border:1px solid #8faeb8;border-radius:9px;padding:12px;font:inherit}.lead-form textarea{min-height:84px}.lead-form .consent{display:flex;gap:9px;align-items:flex-start;font-weight:400}.lead-form .consent input{width:auto;margin-top:4px}.form-status{padding:12px;border-radius:9px;background:#edf7f4}.form-status.error{background:#fff0ed;color:#842b20}.reference{font-size:1.35rem;color:#0b3a53;font-weight:800}</style>\n</head>\n<body>\n  <a class=\"skip\" href=\"#main\">Ir al contenido</a>\n  <header class=\"topbar\">\n    <a class=\"brand brand-motion\" href=\"#inicio\" aria-label=\"Salvación M, inicio; pulsa para reproducir la animación\">\n      <svg viewBox=\"0 0 430 96\" role=\"img\" aria-labelledby=\"header-logo-title header-logo-desc\">\n        <title id=\"header-logo-title\">Salvación M</title>\n        <desc id=\"header-logo-desc\">Dos figuras humanas curvas forman una M de acompañamiento y protección.</desc>\n        <g aria-hidden=\"true\">\n          <g class=\"person-left\"><circle cx=\"29\" cy=\"17\" r=\"10\" fill=\"#0B3A53\"/><path d=\"M14 82V36c0-10 10-16 18-9l32 30v16c-2 2-4 2-5 0L30 46v7c0 13-6 23-16 29Z\" fill=\"#0B3A53\"/></g>\n          <g class=\"person-right\"><circle cx=\"99\" cy=\"17\" r=\"10\" fill=\"#008C8C\"/><path d=\"M114 82V36c0-10-10-16-18-9L64 57v16c2 2 4 2 5 0l29-27v7c0 13 6 23 16 29Z\" fill=\"#1F8A5B\"/></g>\n          <path class=\"embrace-line\" d=\"M26 36c9 3 17 10 24 17 5 5 10 9 14 9s9-4 14-9c7-7 15-14 24-17\" fill=\"none\" stroke=\"#fff\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n        </g>\n        <g class=\"wordmark\"><text x=\"134\" y=\"50\" fill=\"#0B3A53\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"28\" font-weight=\"800\" letter-spacing=\"2\">SALVACIÓN <tspan fill=\"#1F8A5B\">M</tspan></text><text x=\"135\" y=\"72\" fill=\"#53666F\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"11.5\" font-weight=\"600\" letter-spacing=\".35\">ORIENTACIÓN Y ACOMPAÑAMIENTO EN SALUD</text></g>\n      </svg>\n    </a>\n    <button class=\"menu\" aria-expanded=\"false\" aria-controls=\"nav\">Menú</button>\n    <nav id=\"nav\" aria-label=\"Principal\">\n      <a href=\"#problemas\">Problemas frecuentes</a><a href=\"#como\">Cómo ayudamos</a><a href=\"#recursos\">Recursos</a><a href=\"#nosotros\">Nosotros</a>\n      <a class=\"nav-cta\" href=\"#orientador\">Cuéntanos tu caso</a>\n    </nav>\n  </header>\n\n  <main id=\"main\">\n    <section class=\"hero\" id=\"inicio\">\n      <div class=\"hero-copy\">\n        <p class=\"eyebrow\">Orientación clara para actuar</p>\n        <h1 data-hero-title>Tu salud,<br><span>nuestros derechos.</span></h1>\n        <p class=\"lead\">Si una EPS, IPS o farmacia está demorando o negando un servicio, empieza por contar qué está pasando. La consulta inicial es gratuita; después se informa el alcance y el precio de cualquier servicio adicional.</p>\n        <div class=\"actions\"><a class=\"button primary\" href=\"#orientador\">Cuéntanos tu caso</a><a class=\"button ghost\" href=\"#como\">Cómo podemos ayudarte</a></div>\n        <p class=\"fine\">Salvación M es un servicio independiente de orientación. No somos EPS, IPS, clínica, autoridad pública ni servicio de urgencias.</p>\n      </div>\n      <aside class=\"route-card\" aria-label=\"Ruta de orientación\">\n        <p class=\"step-label\">TU RUTA</p>\n        <ol><li><b>Cuéntanos el problema</b><span>En palabras sencillas.</span></li><li><b>Ordenamos la información</b><span>Fechas, respuestas y documentos.</span></li><li><b>Identificamos opciones</b><span>Pasos claros y límites.</span></li></ol>\n      </aside>\n    </section>\n\n    <section class=\"section\" id=\"problemas\">\n      <div class=\"section-head\"><p class=\"eyebrow\">Empieza por tu situación</p><h2>¿Qué problema tienes?</h2><p>Elige la opción que más se parece a lo que ocurre. No necesitas conocer el nombre del trámite.</p></div>\n      <aside class=\"urgent-check\" aria-labelledby=\"urgent-title\">\n        <div class=\"urgent-check-icon\" aria-hidden=\"true\">!</div>\n        <div class=\"urgent-check-copy\"><p class=\"eyebrow\">Primero, lo importante</p><h3 id=\"urgent-title\">¿Tu situación requiere atención inmediata?</h3><p>Si hay riesgo para la vida o la integridad, busca atención de urgencias. No esperes una orientación digital.</p></div>\n        <div class=\"urgent-check-actions\"><a class=\"button urgent-action\" href=\"#orientador\" data-urgent-choice=\"yes\">Sí, es urgente</a><a class=\"button urgent-secondary\" href=\"#orientador\" data-urgent-choice=\"unknown\">No estoy seguro</a></div>\n      </aside>\n      <p class=\"problem-prompt\">Si no es una urgencia, selecciona la situación principal:</p>\n      <div class=\"problem-grid\">\n        <button class=\"problem\" data-problem=\"medicamento\"><span class=\"problem-icon\" aria-hidden=\"true\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#008c8c\" stroke-width=\"1.9\"><path d=\"M8.2 5.2a4.2 4.2 0 0 1 5.9 0l4.7 4.7a4.2 4.2 0 0 1-5.9 5.9l-4.7-4.7a4.2 4.2 0 0 1 0-5.9Z\"/><path d=\"m10.3 7.3 6.4 6.4M6.5 17.5h5M9 15v5\"/></svg></span><b>No me entregan un medicamento</b><small>Hay orden médica, pero la entrega no ocurre.</small><i aria-hidden=\"true\">Elegir</i></button>\n        <button class=\"problem\" data-problem=\"procedimiento\"><span class=\"problem-icon\" aria-hidden=\"true\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#008c8c\" stroke-width=\"1.9\"><path d=\"M12 20a8 8 0 1 0 0-16 8 8 0 0 0 0 16Z\"/><path d=\"m8.5 12 2.3 2.3 4.7-4.7\"/></svg></span><b>No autorizan mi procedimiento</b><small>La autorización está negada o demorada.</small><i aria-hidden=\"true\">Elegir</i></button>\n        <button class=\"problem\" data-problem=\"especialista\"><span class=\"problem-icon\" aria-hidden=\"true\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#008c8c\" stroke-width=\"1.9\"><circle cx=\"12\" cy=\"8\" r=\"3\"/><path d=\"M5.5 20c.5-3.2 2.7-5 6.5-5s6 1.8 6.5 5M18.5 5.5h3M20 4v3\"/></svg></span><b>No consigo cita o especialista</b><small>No hay agenda o la espera se prolonga.</small><i aria-hidden=\"true\">Elegir</i></button>\n        <button class=\"problem\" data-problem=\"continuidad\"><span class=\"problem-icon\" aria-hidden=\"true\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#008c8c\" stroke-width=\"1.9\"><path d=\"M7 7h8.5M15.5 7 18 9.5 15.5 12M17 17H8.5M8.5 17 6 14.5 8.5 12\"/><path d=\"M18 9.5a7 7 0 0 1-1 7.5M6 14.5a7 7 0 0 1 1-7.5\"/></svg></span><b>Interrumpieron mi tratamiento</b><small>Un tratamiento en curso dejó de prestarse.</small><i aria-hidden=\"true\">Elegir</i></button>\n        <button class=\"problem\" data-problem=\"negacion\"><span class=\"problem-icon\" aria-hidden=\"true\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#008c8c\" stroke-width=\"1.9\"><circle cx=\"12\" cy=\"12\" r=\"8\"/><path d=\"m8.5 8.5 7 7M15.5 8.5l-7 7\"/></svg></span><b>Me negaron un servicio</b><small>Recibiste una negativa verbal o escrita.</small><i aria-hidden=\"true\">Elegir</i></button>\n      </div>\n    </section>\n\n    <section class=\"orientador-wrap\" id=\"orientador\">\n      <div class=\"orientador-intro\"><p class=\"eyebrow light\">Consulta inicial gratuita</p><h2>Cuéntanos tu caso</h2><p>Responde cinco preguntas y recibe una ruta inicial. Si decides solicitar revisión, completa tus datos y, si deseas, indica una fecha preferida.</p><div class=\"privacy-note\">No incluyas diagnósticos ni historia clínica. Solo guardaremos los datos cuando autorices y envíes la solicitud.</div></div>\n      <form id=\"caseForm\" class=\"wizard\" novalidate>\n        <input type=\"hidden\" name=\"entity\" value=\"por_confirmar\"><input type=\"hidden\" name=\"order\" value=\"por_confirmar\"><input type=\"hidden\" name=\"action\" value=\"orientacion_inicial\">\n        <div class=\"progress\"><span id=\"progressText\">Paso 1 de 5</span><progress id=\"progress\" value=\"1\" max=\"5\">20%</progress></div>\n        <fieldset class=\"panel active\" data-step=\"1\"><legend>¿Cuál es el problema principal?</legend>\n          <div class=\"choices\">\n            <label><input type=\"radio\" name=\"problem\" value=\"medicamento\" required><span>No entregan un medicamento</span></label>\n            <label><input type=\"radio\" name=\"problem\" value=\"procedimiento\"><span>No autorizan un procedimiento</span></label>\n            <label><input type=\"radio\" name=\"problem\" value=\"especialista\"><span>No asignan cita o especialista</span></label>\n            <label><input type=\"radio\" name=\"problem\" value=\"continuidad\"><span>Interrumpieron un tratamiento</span></label>\n            <label><input type=\"radio\" name=\"problem\" value=\"negacion\"><span>Negaron un servicio</span></label>\n          </div>\n        </fieldset>\n        <fieldset class=\"panel\" data-step=\"2\"><legend>¿Existe un riesgo inmediato?</legend><p class=\"help\">Por ejemplo: dificultad grave para respirar, pérdida de conciencia o riesgo evidente para la vida.</p>\n          <div class=\"choices\"><label><input type=\"radio\" name=\"urgent\" value=\"yes\" required><span>Sí, puede ser una emergencia</span></label><label><input type=\"radio\" name=\"urgent\" value=\"no\"><span>No identifico un riesgo inmediato</span></label><label><input type=\"radio\" name=\"urgent\" value=\"unknown\"><span>No estoy seguro</span></label></div>\n        </fieldset>\n        <fieldset class=\"panel\" data-step=\"3\"><legend>¿Quién está poniendo la barrera?</legend><p class=\"help\">Elige la entidad que te dio la respuesta o donde ocurrió la dificultad.</p><div class=\"choices\"><label><input type=\"radio\" name=\"entity_choice\" value=\"eps\" required><span>Mi EPS</span></label><label><input type=\"radio\" name=\"entity_choice\" value=\"ips\"><span>Una IPS, clínica u hospital</span></label><label><input type=\"radio\" name=\"entity_choice\" value=\"pharmacy\"><span>Una farmacia o proveedor</span></label><label><input type=\"radio\" name=\"entity_choice\" value=\"unknown\"><span>No estoy seguro</span></label></div></fieldset>\n        <fieldset class=\"panel\" data-step=\"4\"><legend>¿Qué soporte tienes?</legend><div class=\"choices\"><label><input type=\"radio\" name=\"support\" value=\"written\" required><span>Respuesta o negación escrita</span></label><label><input type=\"radio\" name=\"support\" value=\"order\"><span>Orden o fórmula médica</span></label><label><input type=\"radio\" name=\"support\" value=\"verbal\"><span>Respuesta verbal</span></label><label><input type=\"radio\" name=\"support\" value=\"none\"><span>Aún no tengo soporte</span></label></div></fieldset>\n        <fieldset class=\"panel\" data-step=\"5\"><legend>¿Hace cuánto ocurre?</legend><div class=\"choices\"><label><input type=\"radio\" name=\"time\" value=\"today\" required><span>Hoy o ayer</span></label><label><input type=\"radio\" name=\"time\" value=\"week\"><span>Entre 3 y 7 días</span></label><label><input type=\"radio\" name=\"time\" value=\"month\"><span>Más de una semana</span></label><label><input type=\"radio\" name=\"time\" value=\"unknown\"><span>No lo sé</span></label></div></fieldset>\n        <p id=\"formError\" class=\"error\" role=\"alert\"></p>\n        <div class=\"wizard-actions\"><button type=\"button\" id=\"prev\" class=\"button ghost\" hidden>Anterior</button><button type=\"button\" id=\"next\" class=\"button primary\">Continuar</button><button type=\"submit\" id=\"finish\" class=\"button primary\" hidden>Ver orientación</button></div>\n      </form>\n      <div id=\"result\" class=\"result\" hidden tabindex=\"-1\"></div>\n    </section>\n\n    <section class=\"section split\" id=\"como\"><div><p class=\"eyebrow\">Un servicio delimitado</p><h2>Te ayudamos a entender, ordenar y actuar</h2></div><div class=\"service-list\"><article><b>Orientación inicial</b><p>Identificamos información faltante, entidad involucrada y ruta posible.</p></article><article><b>Revisión del caso</b><p>Analizamos documentos y respuestas dentro del alcance contratado.</p></article><article><b>Acompañamiento</b><p>Preparamos contigo el siguiente paso, sin garantizar decisiones de terceros.</p></article></div></section>\n\n    <section class=\"section resources\" id=\"recursos\"><div class=\"section-head\"><p class=\"eyebrow\">Para tomar decisiones informadas</p><h2>Recursos esenciales</h2></div><div class=\"resource-grid\"><article><span>Guía</span><h3>Cómo organizar un caso</h3><p>Una cronología simple puede mostrar qué ocurrió, cuándo y quién respondió.</p></article><article><span>Lista</span><h3>Documentos útiles</h3><p>Orden médica, autorización, respuesta, radicado y evidencia de seguimiento.</p></article><article><span>Directorio</span><h3>Canales institucionales</h3><p>Identifica el canal oficial antes de compartir información sensible.</p></article></div></section>\n\n    <section class=\"section about\" id=\"nosotros\"><div><p class=\"eyebrow light\">Salvación M</p><h2>Humanidad para escuchar.<br>Rigor para orientar.</h2></div><p>Responsable: Daniel Enrique Vergel González Rubio, abogado, C.C. 72.255.284. La consulta inicial es gratuita. Si el caso requiere un servicio adicional, su alcance y precio se informan antes de contratar. No ofrecemos pagos en línea.</p></section>\n\n    <section class=\"section\" id=\"privacidad\"><div class=\"section-head\"><p class=\"eyebrow\">Transparencia</p><h2>Política de privacidad</h2></div><div><p><b>Responsable:</b> Daniel Enrique Vergel González Rubio, C.C. 72.255.284. Contacto: <a href=\"mailto:devergel@yahoo.com\">devergel@yahoo.com</a> y WhatsApp <a href=\"https://wa.me/573012370047\">301 237 0047</a>.</p><p>Los datos suministrados voluntariamente se tratarán para responder consultas, evaluar casos, gestionar citas, prestar servicios contratados, comunicarnos, conservar constancias y cumplir obligaciones legales. Los datos de salud son sensibles: no deben enviarse mediante este formulario; si posteriormente fueran indispensables, se solicitará autorización explícita.</p><p>El titular puede conocer, actualizar, rectificar y solicitar supresión; pedir prueba de autorización; conocer el uso; presentar quejas ante la autoridad competente; y revocar la autorización cuando legalmente proceda.</p><p>Aplicamos minimización, acceso restringido, confidencialidad y conservación limitada. No vendemos datos. Las respuestas solo se almacenan cuando el titular envía voluntariamente la solicitud; el consentimiento queda asociado a su referencia.</p><p><b>Vigencia:</b> 21 de septiembre de 2026. Política elaborada bajo la Ley 1581 de 2012 y sus normas reglamentarias aplicables.</p></div></section>\n\n    <section class=\"section split\" id=\"terminos\"><div><p class=\"eyebrow\">Condiciones del servicio</p><h2>Términos de consulta y contratación</h2></div><div><p>La consulta inicial es gratuita y no crea por sí sola mandato, representación judicial ni obligación de aceptar el caso.</p><p>Si se propone un servicio adicional, antes de contratar se informarán por escrito objeto, alcance, exclusiones, honorarios, forma de pago, duración estimada y terminación. No existe pasarela de pago en este sitio.</p><p>Salvación M no presta atención médica, no sustituye urgencias ni garantiza decisiones administrativas o judiciales. La contratación se perfecciona mediante aceptación expresa de la propuesta correspondiente.</p></div></section>\n\n    <section class=\"cta\"><p class=\"eyebrow\">Tu siguiente paso puede ser más claro</p><h2>Empieza por contarnos qué está pasando.</h2><a class=\"button primary\" href=\"#orientador\">Iniciar orientación</a></section>\n  </main>\n\n  <footer><div class=\"brand inverse\"><img src=\"logo-salvacion-m-inverse.svg\" alt=\"Salvación M — Tu salud, nuestros derechos\" width=\"430\" height=\"96\"></div><div><b>Información</b><a href=\"#como\">Alcance</a><a href=\"#privacidad\">Privacidad</a><a href=\"#terminos\">Términos</a><a href=\"mailto:devergel@yahoo.com\">devergel@yahoo.com</a><a href=\"https://wa.me/573012370047\">WhatsApp 301 237 0047</a></div><div><b>Importante</b><p>No prestamos atención médica ni sustituimos servicios de urgencias. Ante una emergencia, acude a los canales oficiales de atención.</p></div><p class=\"copyright\">© 2026 Salvación M · Daniel Enrique Vergel González Rubio, abogado · C.C. 72.255.284</p></footer>\n  <script src=\"app.js?v=12\"></script>\n  <script src=\"contact.js?v=1\"></script>\n</body></html>\n","type":"text/html; charset=utf-8"},"/styles.css":{"body":":root{--navy:#0b3a53;--navy2:#062b3d;--teal:#008c8c;--green:#1f8a5b;--mint:#45d2bd;--ink:#17242b;--muted:#53666f;--mist:#eaf4f6;--line:#cadde2;--white:#fff;--amber:#b96300;--red:#b42318;--radius:18px;--shadow:0 18px 50px rgba(11,58,83,.11)}\n*{box-sizing:border-box}\n[hidden]{display:none!important}\nhtml{scroll-behavior:smooth}\nbody{margin:0;color:var(--ink);font-family:Arial,\"Helvetica Neue\",sans-serif;font-size:16px;line-height:1.58;background:#fff}\n.skip{position:absolute;left:-999px;top:8px;background:#fff;color:#000;padding:10px;z-index:99}\n.skip:focus{left:8px}\n.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;padding:0 clamp(20px,5vw,76px);border-bottom:1px solid var(--line);position:sticky;top:0;background:rgba(255,255,255,.96);backdrop-filter:blur(12px);z-index:20}\n.brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:var(--navy);font-weight:800;letter-spacing:.04em}\n.brand small{display:block;font-size:.68rem;font-weight:500;letter-spacing:0;color:var(--muted)}\n.mark{display:grid;place-items:center;width:42px;height:42px;border-radius:13px;background:var(--navy);color:#fff;font-size:1.3rem}\n.topbar nav{display:flex;align-items:center;gap:24px}\n.topbar nav a{color:var(--ink);text-decoration:none;font-weight:650;font-size:.92rem}\n.topbar nav a:not(.nav-cta){position:relative;padding:9px 0;transition:color .2s ease,transform .2s cubic-bezier(.2,.75,.25,1)}\n.topbar nav a:not(.nav-cta)::after{content:\"\";position:absolute;left:0;right:0;bottom:3px;height:2px;border-radius:999px;background:var(--teal);transform:scaleX(0);transform-origin:center;transition:transform .2s cubic-bezier(.2,.75,.25,1)}\n.topbar nav a:not(.nav-cta):hover,.topbar nav a:not(.nav-cta):focus-visible,.topbar nav a:not(.nav-cta)[aria-current=\"location\"]{color:var(--teal);transform:translateY(-1px)}\n.topbar nav a:not(.nav-cta):hover::after,.topbar nav a:not(.nav-cta):focus-visible::after,.topbar nav a:not(.nav-cta)[aria-current=\"location\"]::after{transform:scaleX(1)}\n.topbar nav a:not(.nav-cta):focus-visible{outline:3px solid rgba(0,140,140,.22);outline-offset:4px;border-radius:3px}\n.topbar .nav-cta{padding:11px 18px;background:var(--navy);color:#fff;border-radius:999px;transform-origin:center;will-change:transform,box-shadow}\n.topbar .nav-cta.is-pulsing{animation:nav-cta-pulse .38s cubic-bezier(.2,.75,.25,1)}\n@keyframes nav-cta-pulse{0%{transform:scale(1);box-shadow:0 0 0 0 rgba(69,210,189,.48)}35%{transform:scale(.97);box-shadow:0 0 0 4px rgba(69,210,189,.34)}100%{transform:scale(1);box-shadow:0 0 0 14px rgba(69,210,189,0)}}\n.menu{display:none}\n.hero{min-height:calc(100vh - 82px);display:grid;grid-template-columns:minmax(0,1.25fr) minmax(300px,.75fr);gap:7vw;align-items:center;padding:clamp(55px,8vw,110px) clamp(22px,8vw,120px);background:radial-gradient(ellipse at 12% 18%,rgba(69,210,189,.30) 0,rgba(69,210,189,0) 46%),radial-gradient(ellipse at 86% 17%,rgba(115,93,224,.20) 0,rgba(115,93,224,0) 48%),radial-gradient(ellipse at 74% 86%,rgba(31,138,91,.24) 0,rgba(31,138,91,0) 50%),linear-gradient(135deg,#fff 0%,#f7fcfd 44%,#e7f5f6 100%);background-size:145% 145%,155% 155%,140% 140%,100% 100%;background-position:0% 25%,100% 10%,78% 100%,center;animation:aurora-derechos 16s ease-in-out infinite alternate}\n.eyebrow{color:var(--teal);font-size:.78rem;font-weight:800;letter-spacing:.13em;text-transform:uppercase}\n.eyebrow.light{color:var(--mint)}\nh1,h2,h3,p{margin-top:0}\nh1{font-size:clamp(3rem,7.4vw,7.8rem);line-height:.88;letter-spacing:-.065em;color:var(--navy);margin-bottom:30px}\n/* Todos los tonos del lema superan 3:1 sobre el fondo claro del hero. */\nh1>span{display:inline-block;color:var(--teal);background:linear-gradient(100deg,#0b3a53 0%,#005e70 26%,#0b6b52 52%,#5849b5 76%,#0b3a53 100%);background-size:300% 100%;background-position:0% 50%;-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;animation:lema-cromatico 5.6s ease-in-out infinite}\n.hero-title-line{display:inline-block}\n.hero-letter{display:inline-block;opacity:0;transform:translateY(.28em);animation:hero-letter-in .42s cubic-bezier(.2,.75,.25,1) both;animation-delay:calc(.38s + var(--letter-index) * .035s)}\nhtml.hero-intro-pending body:before{content:\"\";position:fixed;inset:0;z-index:9999;background:#fff;pointer-events:none;animation:hero-white-intro .75s ease forwards}\nh2{font-size:clamp(2rem,4vw,4.2rem);line-height:1.02;letter-spacing:-.045em;color:var(--navy)}\n.lead{font-size:clamp(1.08rem,1.6vw,1.35rem);max-width:720px;color:var(--muted)}\n.actions{display:flex;gap:12px;flex-wrap:wrap;margin:30px 0}\n.button{border:0;border-radius:999px;padding:14px 22px;font-size:1rem;font-weight:750;cursor:pointer;text-decoration:none;display:inline-flex;justify-content:center;align-items:center;min-height:48px}\n.button.primary{background:var(--green);color:#fff}\n.button.primary:hover,.button.primary:focus{background:#126b43;outline:3px solid rgba(31,138,91,.28);outline-offset:2px}\n.button.ghost{background:#fff;color:var(--navy);border:2px solid var(--line)}\n.actions .button{position:relative;isolation:isolate;transition:transform .22s cubic-bezier(.2,.75,.25,1),box-shadow .22s cubic-bezier(.2,.75,.25,1),background-color .22s ease,border-color .22s ease}\n.actions .button:focus-visible{outline:3px solid rgba(0,140,140,.7);outline-offset:4px}\n.actions .button.primary:hover,.actions .button.primary:focus-visible{transform:translateY(-3px);box-shadow:0 11px 0 rgba(12,91,63,.14),0 16px 30px rgba(31,138,91,.30)}\n.actions .button.ghost:hover,.actions .button.ghost:focus-visible{transform:translateY(-3px);border-color:var(--teal);background:#f7ffff;box-shadow:0 9px 0 rgba(11,58,83,.07),0 14px 28px rgba(11,58,83,.14)}\n.actions .button:active{transform:translateY(0) scale(.97);box-shadow:0 3px 10px rgba(11,58,83,.12)}\n.fine{font-size:.86rem;color:var(--muted);max-width:660px}\n.route-card{background:var(--navy);color:#fff;padding:36px;border-radius:30px;box-shadow:0 28px 72px rgba(6,43,61,.28),0 8px 22px rgba(11,58,83,.16)}\n.step-label{font-size:.75rem;letter-spacing:.14em;color:var(--mint);font-weight:800}\n.route-card ol{padding:0;margin:0;list-style:none;counter-reset:item;position:relative}\n.route-card ol:before{content:\"\";position:absolute;left:15px;top:38px;bottom:38px;width:2px;border-radius:999px;background:linear-gradient(var(--mint),rgba(69,210,189,.26));pointer-events:none}\n.route-card li{counter-increment:item;padding:20px 0 20px 52px;border-bottom:1px solid rgba(255,255,255,.18);position:relative}\n.route-card li:before{content:counter(item);position:absolute;z-index:1;left:0;top:22px;width:32px;height:32px;display:grid;place-items:center;border:1px solid var(--mint);border-radius:50%;background:var(--navy);color:var(--mint)}\n.route-card li:first-child:before{box-shadow:0 0 0 5px rgba(69,210,189,.16),0 0 24px rgba(69,210,189,.28)}\n.route-card span{display:block;color:#c9dde5;font-size:.9rem}\n.section{padding:clamp(70px,9vw,130px) clamp(22px,8vw,120px)}\n.section#problemas{background:radial-gradient(ellipse at 7% 14%,rgba(69,210,189,.25) 0,rgba(69,210,189,0) 43%),radial-gradient(ellipse at 94% 12%,rgba(79,105,210,.16) 0,rgba(79,105,210,0) 43%),radial-gradient(ellipse at 66% 92%,rgba(31,138,91,.18) 0,rgba(31,138,91,0) 48%),linear-gradient(135deg,#faffff 0%,#f2fbfc 48%,#edf8f4 100%);background-size:145% 145%,160% 160%,150% 150%,100% 100%;background-position:0% 22%,100% 8%,74% 100%,center;animation:aurora-problemas 18s ease-in-out infinite alternate}\n.section-head{max-width:760px;margin-bottom:44px}\n.section-head>p:last-child{color:var(--muted);font-size:1.1rem}\n.urgent-check{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:22px;padding:25px 28px;margin:0 0 28px;border:1px solid #f1c9a8;border-radius:24px;background:linear-gradient(110deg,#fff7ef,#fffdf8);box-shadow:0 16px 38px rgba(142,81,14,.09)}\n.urgent-check-icon{display:grid;place-items:center;flex:none;width:44px;height:44px;border-radius:50%;background:#9a5008;color:#fff;font-size:1.5rem;font-weight:900}\n.urgent-check-copy .eyebrow{margin-bottom:5px;color:#9a5008}.urgent-check-copy h3{margin:0 0 3px;font-size:1.25rem;color:#552e08}.urgent-check-copy p:last-child{margin:0;color:#725a48;font-size:.95rem}\n.urgent-check-actions{display:flex;gap:10px;flex-wrap:wrap}.urgent-action{background:#9a5008;color:#fff}.urgent-action:hover,.urgent-action:focus-visible{background:#753a04;outline:3px solid rgba(154,80,8,.25);outline-offset:3px}.urgent-secondary{background:transparent;color:#552e08;border:1px solid #dcb991}.urgent-secondary:hover,.urgent-secondary:focus-visible{background:#fff;color:#552e08;outline:3px solid rgba(154,80,8,.22);outline-offset:3px}\n.problem-prompt{margin:0 0 14px;color:var(--navy);font-weight:750}\n.problem-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}\n.problem{text-align:left;position:relative;border:1px solid var(--line);background:#fff;border-radius:22px;padding:22px;min-height:218px;color:var(--ink);cursor:pointer;overflow:hidden;transition:transform .2s ease,border-color .2s ease,box-shadow .2s ease,background .2s ease}\n.problem:after{content:\"\";position:absolute;left:22px;right:22px;bottom:0;height:3px;border-radius:99px;background:var(--teal);transform:scaleX(0);transform-origin:left;transition:transform .22s ease}\n.problem:hover,.problem:focus-visible{transform:translateY(-5px);border-color:var(--teal);background:#fbffff;box-shadow:var(--shadow);outline:none}.problem:hover:after,.problem:focus-visible:after{transform:scaleX(1)}\n.problem-icon{display:grid;place-items:center;width:46px;height:46px;border-radius:14px;background:var(--mist);color:var(--teal)}.problem-icon svg{display:block;width:26px;height:26px;fill:none;stroke-linecap:round;stroke-linejoin:round}\n.problem b{display:block;max-width:260px;font-size:1.12rem;line-height:1.22;margin:22px 0 9px}.problem small{display:block;max-width:300px;color:var(--muted);font-size:.9rem;line-height:1.45}.problem i{position:absolute;right:22px;bottom:18px;color:var(--teal);font-size:.82rem;font-style:normal;font-weight:800;opacity:0;transform:translateX(-5px);transition:opacity .2s ease,transform .2s ease}.problem:hover i,.problem:focus-visible i{opacity:1;transform:none}\n.orientador-wrap{display:grid;grid-template-columns:.7fr 1.3fr;gap:6vw;background:var(--navy2);color:#fff;padding:clamp(70px,9vw,120px) clamp(22px,8vw,120px)}\n.orientador-wrap h2{color:#fff}\n.privacy-note{border-left:4px solid var(--mint);padding:12px 16px;background:rgba(255,255,255,.07)}\n.wizard,.result{background:#fff;color:var(--ink);border-radius:24px;padding:clamp(22px,4vw,46px)}\n.progress{display:flex;align-items:center;gap:16px;color:var(--muted);font-size:.9rem;margin-bottom:30px}\n.progress progress{width:100%;accent-color:var(--green)}\nfieldset{border:0;padding:0;margin:0}\nlegend{font-size:1.7rem;font-weight:800;color:var(--navy);line-height:1.15;margin-bottom:12px}\n.help{color:var(--muted)}\n.panel{display:none}\n.panel.active{display:block}\n.choices{display:grid;gap:10px;margin-top:24px}\n.choices label{position:relative}\n.choices input{position:absolute;opacity:0}\n.choices span{display:block;padding:16px 18px;border:2px solid var(--line);border-radius:12px;cursor:pointer}\n.choices input:checked+span{border-color:var(--teal);background:var(--mist);font-weight:700}\n.choices input:focus+span{outline:3px solid rgba(0,140,140,.25);outline-offset:2px}\n.wizard-actions{display:flex;justify-content:space-between;margin-top:28px}\n.error{color:var(--red);font-weight:700;min-height:1.5em}\n.result h3{font-size:2rem;color:var(--navy)}\n.route-result{display:grid;gap:12px;margin:22px 0}.route-result article{display:grid;grid-template-columns:34px 1fr;gap:13px;padding:15px 16px;border:1px solid var(--line);border-radius:14px;background:#f8fcfc}.route-result span{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:var(--teal);color:#fff;font-size:.82rem;font-weight:800}.route-result b{display:block;color:var(--navy);margin-bottom:2px}.route-result p{margin:0;color:var(--muted);font-size:.94rem}.route-disclaimer{padding:13px 15px;border-left:4px solid var(--mint);background:var(--mist);color:#31505b;font-size:.92rem}\n.save-confirmation{display:flex;gap:11px;align-items:flex-start;margin:0 0 20px;padding:14px 16px;border:1px solid #a8dac5;border-radius:14px;background:#effaf4;color:#175a3b}.save-confirmation strong{display:block}.save-confirmation p{margin:1px 0 0;font-size:.9rem}.save-confirmation-mark{display:grid;place-items:center;flex:none;width:25px;height:25px;border-radius:50%;background:var(--green);color:#fff;font-weight:900}\n.urgent{padding:18px;border-left:5px solid var(--red);background:#fff0f0}\n.result ul{padding-left:20px}\n.split{display:grid;grid-template-columns:1fr 1fr;gap:8vw;background:var(--mist)}\n.service-list article{padding:20px 0;border-bottom:1px solid var(--line)}\n.service-list b{font-size:1.25rem;color:var(--navy)}\n.service-list p{margin:5px 0;color:var(--muted)}\n.resource-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}\n.resource-grid article{padding:28px;border:1px solid var(--line);border-radius:var(--radius)}\n.resource-grid span{font-size:.75rem;color:var(--teal);font-weight:800;text-transform:uppercase;letter-spacing:.1em}\n.about{background:var(--navy);color:#d8e8ed;display:grid;grid-template-columns:1fr 1fr;gap:8vw}\n.about h2{color:#fff}\n.about>p{font-size:1.15rem}\n.cta{text-align:center;padding:100px 20px;background:#f5fbfb}\n.cta h2{max-width:780px;margin:0 auto 30px}\nfooter{background:#061f2b;color:#cfe1e7;padding:58px clamp(22px,8vw,120px);display:grid;grid-template-columns:1.2fr .7fr 1fr;gap:50px;position:relative}\n.brand.inverse{color:#fff}\n.brand.inverse small{color:#9fc0cb}\nfooter div{display:flex;flex-direction:column;gap:8px}\nfooter a{color:#fff}\n.copyright{grid-column:1/-1;border-top:1px solid #365360;padding-top:22px;font-size:.85rem}\n@keyframes aurora-derechos{0%{background-position:0% 25%,100% 10%,78% 100%,center}100%{background-position:58% 72%,38% 86%,18% 18%,center}}\n@keyframes aurora-problemas{0%{background-position:0% 22%,100% 8%,74% 100%,center}100%{background-position:44% 70%,38% 82%,15% 25%,center}}\n@keyframes lema-cromatico{0%,100%{background-position:0% 50%}50%{background-position:100% 50%}}\n@keyframes hero-white-intro{0%,35%{opacity:1}100%{opacity:0;visibility:hidden}}\n@keyframes hero-letter-in{to{opacity:1;transform:translateY(0)}}\n@media(max-width:1000px){.urgent-check{grid-template-columns:auto 1fr}.urgent-check-actions{grid-column:2}.problem-grid{grid-template-columns:repeat(2,1fr)}\n.topbar nav{display:none;position:absolute;top:82px;left:0;right:0;background:#fff;padding:20px;flex-direction:column;align-items:stretch}\n.topbar nav.open{display:flex}\n.menu{display:block;border:1px solid var(--line);background:#fff;border-radius:10px;padding:10px}\n.hero,.orientador-wrap,.split,.about{grid-template-columns:1fr}\n.hero{background:radial-gradient(ellipse at 12% 18%,rgba(69,210,189,.30) 0,rgba(69,210,189,0) 46%),radial-gradient(ellipse at 86% 17%,rgba(115,93,224,.20) 0,rgba(115,93,224,0) 48%),radial-gradient(ellipse at 74% 86%,rgba(31,138,91,.24) 0,rgba(31,138,91,0) 50%),linear-gradient(135deg,#fff 0%,#f7fcfd 44%,#e7f5f6 100%);background-size:145% 145%,155% 155%,140% 140%,100% 100%;background-position:0% 25%,100% 10%,78% 100%,center}\n.resource-grid{grid-template-columns:1fr 1fr}\n}\n@media(max-width:620px){.topbar{height:72px;padding:0 16px}\n.brand small{display:none}\n.topbar nav{top:72px}\n.hero{min-height:auto;padding-top:55px}\n.urgent-check{grid-template-columns:1fr;gap:14px;padding:22px}.urgent-check-icon{width:38px;height:38px}.urgent-check-actions{grid-column:auto}.urgent-check-actions .button{flex:1}.problem-grid,.resource-grid{grid-template-columns:1fr}\n.problem{min-height:185px}.problem b{margin-top:20px}.problem i{opacity:1;transform:none}\n.orientador-wrap{padding-left:16px;padding-right:16px}\n.wizard,.result{padding:20px 16px}\n.actions .button{width:100%}\nfooter{grid-template-columns:1fr}\nh1{font-size:3.35rem}\n.copyright{grid-column:auto}\n}\n@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}.section#problemas{animation:none!important}.topbar nav a:not(.nav-cta):hover,.topbar nav a:not(.nav-cta):focus-visible,.topbar nav a:not(.nav-cta)[aria-current=\"location\"]{transform:none}.topbar .nav-cta.is-pulsing{animation:none;background:var(--teal)}\n}\n\n/* Identidad Abrazo M: símbolo y wordmark se conservan como una sola unidad. */\n.brand{gap:0;font-weight:400;letter-spacing:0}\n.brand img{display:block;width:clamp(210px,24vw,310px);height:auto}\n.brand svg{display:block;width:clamp(210px,24vw,310px);height:auto}\n.brand.inverse img{width:min(100%,360px)}\n@media(max-width:620px){.brand img{width:210px}}\n\n/* Header dinámico: conserva jerarquía al inicio y libera espacio durante la lectura. */\n.topbar{transition:height .26s ease,box-shadow .26s ease,padding .26s ease}\n.topbar .brand img{transition:width .26s ease}\n.topbar .brand svg{transition:width .26s ease}\n.topbar.is-compact{height:64px;box-shadow:0 10px 30px rgba(11,58,83,.12)}\n.topbar.is-compact .brand img{width:230px}\n.topbar.is-compact .brand svg{width:230px}\n@media(max-width:1000px){.topbar.is-compact nav{top:64px}}\n@media(max-width:620px){.topbar.is-compact{height:62px}.topbar.is-compact .brand img{width:188px}.topbar.is-compact nav{top:62px}}\n@media(max-width:620px){.topbar.is-compact .brand svg{width:188px}.brand svg{width:210px}}\n@media(prefers-reduced-motion:reduce){.topbar,.topbar .brand img,.topbar .brand svg{transition:none}}\n\n.brand-motion.is-replaying .person-left{animation:brand-meet-left .72s cubic-bezier(.2,.75,.25,1) both}\n.brand-motion.is-replaying .person-right{animation:brand-meet-right .72s cubic-bezier(.2,.75,.25,1) both}\n.brand-motion.is-replaying .embrace-line{animation:brand-reveal .34s .52s ease-out both}\n.brand-motion.is-replaying .wordmark{animation:brand-reveal .42s .66s ease-out both}\n@keyframes brand-meet-left{from{opacity:0;transform:translateX(-14px)}to{opacity:1;transform:translateX(0)}}\n@keyframes brand-meet-right{from{opacity:0;transform:translateX(14px)}to{opacity:1;transform:translateX(0)}}\n@keyframes brand-reveal{from{opacity:0}to{opacity:1}}\n@media(prefers-reduced-motion:reduce){.brand-motion.is-replaying .person-left,.brand-motion.is-replaying .person-right,.brand-motion.is-replaying .embrace-line,.brand-motion.is-replaying .wordmark{animation:none}}\n@media(prefers-reduced-motion:reduce){.hero{animation:none;background-position:30% 45%,58% 42%,48% 58%,center}h1 span{animation:none;background-position:38% 50%}}\n","type":"text/css; charset=utf-8"},"/app.js":{"body":"const menu=document.querySelector('.menu'),nav=document.querySelector('#nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));nav.classList.toggle('open',!open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));\nconst navCta=nav.querySelector('.nav-cta');let ctaPulseTimer;navCta.addEventListener('click',()=>{navCta.classList.remove('is-pulsing');void navCta.offsetWidth;navCta.classList.add('is-pulsing');clearTimeout(ctaPulseTimer);ctaPulseTimer=setTimeout(()=>navCta.classList.remove('is-pulsing'),420)});\nconst sectionLinks=[...nav.querySelectorAll('a[href^=\"#\"]:not(.nav-cta)')],sectionTargets=sectionLinks.map(link=>document.querySelector(link.getAttribute('href'))).filter(Boolean);const markCurrent=id=>sectionLinks.forEach(link=>{const current=link.getAttribute('href')===`#${id}`;if(current)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current')});if('IntersectionObserver'in window){const visibleSections=new Map();const sectionObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>entry.isIntersecting?visibleSections.set(entry.target.id,entry.intersectionRatio):visibleSections.delete(entry.target.id));const current=[...visibleSections].sort((a,b)=>b[1]-a[1])[0];if(current)markCurrent(current[0])},{rootMargin:'-82px 0px -55% 0px',threshold:[0,.2,.5,.8]});sectionTargets.forEach(section=>sectionObserver.observe(section))}\nconst header=document.querySelector('.topbar');let headerFrame=0;const syncHeader=()=>{header.classList.toggle('is-compact',window.scrollY>36);headerFrame=0};window.addEventListener('scroll',()=>{if(!headerFrame)headerFrame=requestAnimationFrame(syncHeader)},{passive:true});syncHeader();\nconst logoLink=document.querySelector('.topbar .brand-motion'),reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)');let logoTimer;function playLogo(){if(reduceMotion.matches)return;logoLink.classList.remove('is-replaying');void logoLink.offsetWidth;logoLink.classList.add('is-replaying');clearTimeout(logoTimer);logoTimer=setTimeout(()=>logoLink.classList.remove('is-replaying'),1200)}logoLink.addEventListener('click',playLogo);playLogo();\nconst heroTitle=document.querySelector('[data-hero-title]');if(document.documentElement.classList.contains('hero-intro-pending')&&heroTitle){const titleText=heroTitle.textContent.replace(/\\s+/g,' ').trim();heroTitle.setAttribute('aria-label',titleText);heroTitle.replaceChildren();let index=0;['Tu salud,','nuestros derechos.'].forEach((line,lineIndex)=>{if(lineIndex)heroTitle.append(document.createElement('br'));const lineWrap=document.createElement('span');lineWrap.className='hero-title-line';lineWrap.setAttribute('aria-hidden','true');for(const character of line){const letter=document.createElement('span');letter.className='hero-letter';letter.style.setProperty('--letter-index',index++);letter.textContent=character===' '?'\\u00a0':character;lineWrap.append(letter)}heroTitle.append(lineWrap)});setTimeout(()=>document.documentElement.classList.remove('hero-intro-pending'),900)}\nconst form=document.querySelector('#caseForm'),panels=[...document.querySelectorAll('.panel')],prev=document.querySelector('#prev'),next=document.querySelector('#next'),finish=document.querySelector('#finish'),error=document.querySelector('#formError'),progress=document.querySelector('#progress'),progressText=document.querySelector('#progressText'),result=document.querySelector('#result'),totalSteps=panels.length;let step=1;\nfunction show(){panels.forEach(p=>p.classList.toggle('active',Number(p.dataset.step)===step));progress.value=step;progress.max=totalSteps;progressText.textContent=`Paso ${step} de ${totalSteps}`;prev.hidden=step===1;next.hidden=step===totalSteps;finish.hidden=step!==totalSteps;error.textContent=''}function valid(){const p=panels[step-1],checked=p.querySelector('input:checked');if(!checked){error.textContent='Selecciona una opción para continuar.';p.querySelector('input').focus();return false}return true}\nnext.addEventListener('click',()=>{if(valid()){step++;show()}});prev.addEventListener('click',()=>{step--;show()});document.querySelectorAll('.problem').forEach(b=>b.addEventListener('click',()=>{document.querySelector(`input[name=\"problem\"][value=\"${b.dataset.problem}\"]`).checked=true;document.querySelector('#orientador').scrollIntoView()}));document.querySelectorAll('[data-urgent-choice]').forEach(link=>link.addEventListener('click',()=>{document.querySelector(`input[name=\"urgent\"][value=\"${link.dataset.urgentChoice}\"]`).checked=true}));\nconst labels={medicamento:'entrega de un medicamento',procedimiento:'autorización de un procedimiento',especialista:'asignación de cita o especialista',continuidad:'continuidad de un tratamiento',negacion:'negación de un servicio'};const entities={eps:'la EPS',ips:'la IPS, clínica u hospital',pharmacy:'la farmacia o proveedor',unknown:'la entidad que debe responder'};const routes={medicamento:{request:'Solicita constancia de disponibilidad y fecha de entrega',record:'Orden o fórmula médica vigente y cualquier respuesta de la entidad.'},procedimiento:{request:'Solicita una respuesta clara sobre la autorización y su estado',record:'Orden médica, solicitud o autorización y respuesta recibida.'},especialista:{request:'Solicita la asignación o una respuesta sobre la disponibilidad de agenda',record:'Orden o remisión, fecha de solicitud y constancias de contacto.'},continuidad:{request:'Solicita la continuidad del servicio y deja registro de la interrupción',record:'Órdenes, autorizaciones previas y fechas en que dejó de prestarse.'},negacion:{request:'Solicita una respuesta escrita, clara y con fecha',record:'La respuesta recibida, radicado o evidencia de que solicitaste el servicio.'}};function restart(){result.hidden=true;form.hidden=false;step=1;show();form.scrollIntoView()}\nfunction routePreview(a){const r=routes[a.problem],support=a.support==='none'?'Aún no tienes soportes; empieza por pedir una constancia o radicado.':a.support==='verbal'?'La respuesta fue verbal; anota fecha, canal y persona que te atendió.':'Conserva el soporte que ya tienes y evita enviar historia clínica por este formulario.';const timing=a.time==='today'?'El hecho es reciente: registra hoy la solicitud y la respuesta.':a.time==='week'?'La espera ya supera varios días: organiza una línea de tiempo breve.':'Reúne las fechas principales para que la revisión identifique la secuencia.';return `<p class=\"eyebrow\">Ruta preliminar</p><h3>Estos son tus siguientes pasos para ${labels[a.problem]}</h3><p>La barrera parece relacionarse con ${entities[a.entity_choice]}. Esta ruta organiza la información antes de pedir acompañamiento.</p><div class=\"route-result\"><article><span>1</span><div><b>Deja una solicitud verificable</b><p>${r.request} ante ${entities[a.entity_choice]}.</p></div></article><article><span>2</span><div><b>Organiza los soportes</b><p>${r.record} ${support}</p></div></article><article><span>3</span><div><b>Prepara una cronología breve</b><p>${timing}</p></div></article></div><p class=\"route-disclaimer\">Esta es una orientación inicial y no sustituye atención médica, urgencias ni una revisión jurídica individual. Salvación M analizará el alcance del caso antes de ofrecer un servicio adicional.</p>`}\nform.addEventListener('submit',e=>{e.preventDefault();if(!valid())return;const d=new FormData(form),urgent=d.get('urgent')==='yes';form.hidden=true;result.hidden=false;if(urgent){result.innerHTML='<p class=\"eyebrow\">Atención prioritaria</p><h3>No esperes una orientación digital</h3><div class=\"urgent\"><b>Si existe riesgo inmediato para la vida o la integridad, acude a un servicio de urgencias o utiliza los canales oficiales de emergencia.</b></div><p>Salvación M no presta atención médica ni realiza triage clínico.</p><button class=\"button ghost\" id=\"restart\">Volver a empezar</button>';document.querySelector('#restart').onclick=restart;result.focus({preventScroll:true});result.scrollIntoView({behavior:reduceMotion.matches?'auto':'smooth',block:'start'});return}const a=Object.fromEntries(d.entries());a.entity=a.entity_choice;a.order=a.support==='order'?'si':'por_confirmar';a.action='orientacion_'+a.problem;try{sessionStorage.setItem('salvacion-m-ruta',JSON.stringify({problem:a.problem,entity:a.entity_choice,support:a.support,time:a.time,saved_at:new Date().toISOString()}))}catch{}result.innerHTML=`<div class=\"save-confirmation\" role=\"status\"><span class=\"save-confirmation-mark\" aria-hidden=\"true\">✓</span><div><strong>Respuestas guardadas temporalmente</strong><p>Tu orientación se generó con estas respuestas. Aún no enviamos información a Salvación M.</p></div></div>${routePreview(a)}<p class=\"eyebrow\">Consulta inicial gratuita</p><h3>¿Quieres que revisemos esta ruta contigo?</h3><p>Deja tus datos y una fecha preferida. La solicitud quedará pendiente de confirmación.</p><form id=\"leadForm\" class=\"lead-form\"><label>Nombre completo<input name=\"name\" autocomplete=\"name\" required maxlength=\"120\"></label><label>WhatsApp<input name=\"phone\" inputmode=\"tel\" autocomplete=\"tel\" required pattern=\"[0-9 +()-]{7,20}\" maxlength=\"20\"></label><label>Correo electrónico<input name=\"email\" type=\"email\" autocomplete=\"email\" required maxlength=\"160\"></label><label>Fecha y hora preferida, si deseas proponer una cita (hora de Colombia)<input name=\"preferred_at\" type=\"datetime-local\"></label><label>Resumen breve, sin historia clínica<textarea name=\"summary\" maxlength=\"700\"></textarea></label><label class=\"consent\"><input name=\"consent\" type=\"checkbox\" required><span>Autorizo el tratamiento de mis datos para gestionar esta consulta conforme a la <a href=\"#privacidad\">política de privacidad</a>.</span></label><div id=\"leadStatus\" class=\"form-status\" hidden></div><div><button class=\"button primary\">Solicitar revisión</button> <button type=\"button\" class=\"button ghost\" id=\"restart\">Revisar respuestas</button></div></form>`;document.querySelector('#restart').onclick=restart;result.focus({preventScroll:true});result.scrollIntoView({behavior:reduceMotion.matches?'auto':'smooth',block:'start'});const lf=document.querySelector('#leadForm');lf.onsubmit=async ev=>{ev.preventDefault();const status=document.querySelector('#leadStatus'),button=lf.querySelector('button[type=\"submit\"]');status.hidden=false;status.textContent='Enviando…';button.disabled=true;try{const c=Object.fromEntries(new FormData(lf).entries()),r=await fetch('/api/consultations',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...a,...c,consent:true})}),p=await r.json();if(!r.ok)throw new Error(p.error||'No fue posible guardar la solicitud.');lf.innerHTML=`<p class=\"eyebrow\">Solicitud recibida</p><h3>Gracias, ${p.name}.</h3><p class=\"reference\">Referencia ${p.reference}</p><p>Tu consulta quedó registrada. La fecha preferida, si la indicaste, queda pendiente de confirmación.</p><a class=\"button primary\" target=\"_blank\" rel=\"noopener\" href=\"${p.whatsapp_url}\">Continuar por WhatsApp</a>`}catch(x){status.className='form-status error';status.textContent=x.message;button.disabled=false}}});\nfinish.addEventListener('click',()=>setTimeout(()=>{if(result.hidden)form.dispatchEvent(new Event('submit',{cancelable:true}));if(!result.hidden){result.focus({preventScroll:true});result.scrollIntoView({behavior:reduceMotion.matches?'auto':'smooth',block:'start'})}},0));\n","type":"application/javascript; charset=utf-8"},"/contact.js":{"body":"  (()=>{\n    const form=document.querySelector('#caseForm'),result=document.querySelector('#result'),error=document.querySelector('#formError');\n    const labels={medicamento:'entrega de un medicamento',procedimiento:'autorización de un procedimiento',especialista:'asignación de cita o especialista',continuidad:'continuidad de un tratamiento',negacion:'negación de un servicio'};\n    const entityLabels={eps:'EPS',ips:'IPS, clínica u hospital',pharmacy:'farmacia o proveedor',unknown:'entidad por confirmar'};\n    const escape=v=>String(v||'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n    const draft=()=>{try{return JSON.parse(sessionStorage.getItem('salvacion-m-contacto')||'{}')}catch{return {}}};\n    const allAnswered=()=>['problem','urgent','entity_choice','support','time'].every(name=>form.querySelector(`input[name=\"${name}\"]:checked`));\n    const goHome=()=>{location.hash='inicio';document.querySelector('#inicio').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});};\n    form.addEventListener('submit',event=>{\n      event.preventDefault();event.stopImmediatePropagation();\n      if(!allAnswered()){error.textContent='Completa cada pregunta antes de ver tu orientación.';return}\n      const answers=Object.fromEntries(new FormData(form).entries());\n      form.hidden=true;result.hidden=false;\n      if(answers.urgent==='yes'){\n        result.innerHTML='<p class=\"eyebrow\">Atención prioritaria</p><h3>No esperes una orientación digital</h3><div class=\"urgent\"><b>Si existe riesgo inmediato para la vida o la integridad, acude a un servicio de urgencias o utiliza los canales oficiales de emergencia.</b></div><p>Salvación M no presta atención médica ni realiza triage clínico.</p><button class=\"button ghost\" type=\"button\" id=\"restart\">Volver a empezar</button>';\n        result.querySelector('#restart').onclick=()=>{result.hidden=true;form.hidden=false;form.reset();goHome()};result.focus({preventScroll:true});result.scrollIntoView({behavior:'smooth',block:'start'});return;\n      }\n      const saved=draft();\n      result.innerHTML=`<div class=\"save-confirmation\" role=\"status\"><span class=\"save-confirmation-mark\" aria-hidden=\"true\">✓</span><div><strong>Respuestas guardadas temporalmente</strong><p>Ya generamos tu orientación. Autoriza el tratamiento de datos para enviar la solicitud a Salvación M.</p></div></div><p class=\"eyebrow\">Ruta preliminar</p><h3>Solicitud para ${labels[answers.problem]}</h3><p>La entidad identificada es: <b>${entityLabels[answers.entity_choice]}</b>. Al enviar, el equipo recibirá tu solicitud para revisar el alcance de la orientación.</p><form id=\"contactForm\" class=\"lead-form\"><label>Nombres<input name=\"first_name\" autocomplete=\"given-name\" required maxlength=\"80\" value=\"${escape(saved.first_name)}\"></label><label>Apellidos<input name=\"last_name\" autocomplete=\"family-name\" required maxlength=\"80\" value=\"${escape(saved.last_name)}\"></label><label>Teléfono o WhatsApp<input name=\"phone\" inputmode=\"tel\" autocomplete=\"tel\" required pattern=\"[0-9 +()-]{7,20}\" maxlength=\"20\" value=\"${escape(saved.phone)}\"></label><label>Dirección de residencia<input name=\"address\" autocomplete=\"street-address\" required maxlength=\"180\" value=\"${escape(saved.address)}\"></label><label>Correo electrónico<input name=\"email\" type=\"email\" autocomplete=\"email\" required maxlength=\"160\" value=\"${escape(saved.email)}\"></label><label>Fecha y hora preferida, si deseas proponer una cita (hora de Colombia)<input name=\"preferred_at\" type=\"datetime-local\"></label><label>Resumen breve, sin historia clínica<textarea name=\"summary\" maxlength=\"500\"></textarea></label><label class=\"consent\"><input name=\"consent\" type=\"checkbox\" required><span>Autorizo a Salvación M el tratamiento de mis datos de identificación, contacto, residencia y respuestas para gestionar esta solicitud, comunicarme y conservar la constancia correspondiente, conforme a la <a href=\"#privacidad\">política de privacidad</a>.</span></label><div id=\"leadStatus\" class=\"form-status\" hidden></div><div><button class=\"button primary\" type=\"submit\">Autorizar y enviar solicitud</button><button class=\"button ghost\" type=\"button\" id=\"restart\">Volver a empezar</button></div></form>`;\n      result.querySelector('#restart').onclick=()=>{result.hidden=true;form.hidden=false;form.reset();goHome()};\n      result.focus({preventScroll:true});result.scrollIntoView({behavior:'smooth',block:'start'});\n      const contactForm=result.querySelector('#contactForm'),requestId=crypto.randomUUID();\n      contactForm.addEventListener('submit',async ev=>{\n        ev.preventDefault();const status=result.querySelector('#leadStatus'),button=contactForm.querySelector('button[type=\"submit\"]'),contact=Object.fromEntries(new FormData(contactForm).entries());\n        status.hidden=false;status.textContent='Enviando solicitud…';button.disabled=true;\n        const name=`${contact.first_name} ${contact.last_name}`.trim();const storedSummary=contact.summary||'';\n        try{const response=await fetch('/api/consultations',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...answers,request_id:requestId,name,phone:contact.phone,email:contact.email,address:contact.address,preferred_at:contact.preferred_at,summary:storedSummary,entity:answers.entity_choice,order:answers.support==='order'?'si':'por_confirmar',action:`orientacion_${answers.problem}`,consent:true})});const payload=await response.json();if(!response.ok)throw new Error(payload.error||'No fue posible guardar la solicitud.');try{sessionStorage.setItem('salvacion-m-contacto',JSON.stringify({first_name:contact.first_name,last_name:contact.last_name,phone:contact.phone,address:contact.address,email:contact.email}))}catch{}result.innerHTML=`<p class=\"eyebrow\">Solicitud recibida</p><h3>Gracias, ${escape(contact.first_name)}.</h3><p class=\"reference\">Referencia ${payload.reference}</p><p>Tu solicitud fue registrada con la autorización otorgada. La fecha preferida, si la indicaste, queda pendiente de confirmación. Volverás al inicio en unos segundos.</p><button class=\"button primary\" type=\"button\" id=\"goHome\">Volver al inicio</button>`;result.querySelector('#goHome').onclick=goHome;setTimeout(goHome,5000)}catch(err){status.className='form-status error';status.textContent=err.message;button.disabled=false}\n      });\n    },true);\n  })();\n\n","type":"application/javascript; charset=utf-8"},"/intro.js":{"body":"if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)document.documentElement.classList.add('hero-intro-pending');\n","type":"application/javascript; charset=utf-8"},"/favicon.svg":{"body":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\"><rect width=\"64\" height=\"64\" rx=\"15\" fill=\"#0B3A53\"/><circle cx=\"19\" cy=\"17\" r=\"6\" fill=\"#fff\"/><circle cx=\"45\" cy=\"17\" r=\"6\" fill=\"#45D2BD\"/><path d=\"M12 48V27c0-5 6-7 9-3l11 14 11-14c3-4 9-2 9 3v21h-8V35L32 49 20 35v13z\" fill=\"#fff\"/></svg>\n","type":"image/svg+xml"},"/logo-salvacion-m.svg":{"body":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 430 96\" role=\"img\" aria-labelledby=\"title desc\">\n  <title id=\"title\">Salvación M</title>\n  <desc id=\"desc\">Dos figuras humanas curvas forman una M de acompañamiento y protección.</desc>\n  <style>\n    .person-left{animation:meet-left .72s cubic-bezier(.2,.75,.25,1) both}\n    .person-right{animation:meet-right .72s cubic-bezier(.2,.75,.25,1) both}\n    .embrace-line{animation:reveal .34s .52s ease-out both}\n    .wordmark{animation:reveal .42s .66s ease-out both}\n    @keyframes meet-left{from{opacity:0;transform:translateX(-14px)}to{opacity:1;transform:translateX(0)}}\n    @keyframes meet-right{from{opacity:0;transform:translateX(14px)}to{opacity:1;transform:translateX(0)}}\n    @keyframes reveal{from{opacity:0}to{opacity:1}}\n    @media (prefers-reduced-motion:reduce){.person-left,.person-right,.embrace-line,.wordmark{animation:none}}\n  </style>\n  <g aria-hidden=\"true\">\n    <g class=\"person-left\"><circle cx=\"29\" cy=\"17\" r=\"10\" fill=\"#0B3A53\"/><path d=\"M14 82V36c0-10 10-16 18-9l32 30v16c-2 2-4 2-5 0L30 46v7c0 13-6 23-16 29Z\" fill=\"#0B3A53\"/></g>\n    <g class=\"person-right\"><circle cx=\"99\" cy=\"17\" r=\"10\" fill=\"#008C8C\"/><path d=\"M114 82V36c0-10-10-16-18-9L64 57v16c2 2 4 2 5 0l29-27v7c0 13 6 23 16 29Z\" fill=\"#1F8A5B\"/></g>\n    <path class=\"embrace-line\" d=\"M26 36c9 3 17 10 24 17 5 5 10 9 14 9s9-4 14-9c7-7 15-14 24-17\" fill=\"none\" stroke=\"#fff\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n  </g>\n  <g class=\"wordmark\"><text x=\"134\" y=\"50\" fill=\"#0B3A53\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"28\" font-weight=\"800\" letter-spacing=\"2\">SALVACIÓN <tspan fill=\"#1F8A5B\">M</tspan></text><text x=\"135\" y=\"72\" fill=\"#53666F\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"11.5\" font-weight=\"600\" letter-spacing=\".35\">ORIENTACIÓN Y ACOMPAÑAMIENTO EN SALUD</text></g>\n</svg>\n","type":"image/svg+xml"},"/logo-salvacion-m-inverse.svg":{"body":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 430 96\" role=\"img\" aria-labelledby=\"title desc\">\n  <title id=\"title\">Salvación M</title>\n  <desc id=\"desc\">Dos figuras humanas curvas forman una M de acompañamiento y protección.</desc>\n  <g aria-hidden=\"true\"><circle cx=\"29\" cy=\"17\" r=\"10\" fill=\"#FFFFFF\"/><circle cx=\"99\" cy=\"17\" r=\"10\" fill=\"#45D2BD\"/><path d=\"M14 82V36c0-10 10-16 18-9l32 30 32-30c8-7 18-1 18 9v46c-10-6-16-16-16-29V46L69 73c-3 3-7 3-10 0L30 46v7c0 13-6 23-16 29Z\" fill=\"#FFFFFF\"/><path d=\"M26 36c9 3 17 10 24 17 5 5 10 9 14 9s9-4 14-9c7-7 15-14 24-17\" fill=\"none\" stroke=\"#061F2B\" stroke-width=\"5\" stroke-linecap=\"round\"/></g>\n  <text x=\"134\" y=\"50\" fill=\"#FFFFFF\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"28\" font-weight=\"800\" letter-spacing=\"2\">SALVACIÓN <tspan fill=\"#45D2BD\">M</tspan></text>\n  <text x=\"135\" y=\"72\" fill=\"#CFE1E7\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"11.5\" font-weight=\"600\" letter-spacing=\".35\">TU SALUD, NUESTROS DERECHOS.</text>\n</svg>\n","type":"image/svg+xml"}};
const securityHeaders={'content-security-policy':"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'",'referrer-policy':'strict-origin-when-cross-origin','x-content-type-options':'nosniff','x-frame-options':'DENY','permissions-policy':'camera=(), microphone=(), geolocation=()','strict-transport-security':'max-age=31536000; includeSubDomains'};
const json=(data,status=200,extra={})=>new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store',...securityHeaders,...extra}});
const clean=(v,n=700)=>String(v??'').trim().slice(0,n);const allowed=(v,list)=>list.includes(v);const iso=()=>new Date().toISOString();
function admin(request,env){const h=request.headers.get('authorization')||'';return env.ADMIN_API_TOKEN&&h===`Bearer ${env.ADMIN_API_TOKEN}`}
// The shared administrative token grants one server-side role. A browser header is
// never an authority for RBAC; distinct users/roles require verified identity.
function role(){return 'admin'}function can(){return true}function actor(request){return clean(request.headers.get('x-crm-actor-id'),120)||'service-admin'}
async function publicCreate(request,env){let b;try{b=await request.json()}catch{return json({error:'Solicitud inválida.'},400)}if(clean(b.website))return json({error:'Solicitud inválida.'},400);const required=['name','phone','email','problem','entity','order','action'];if(required.some(k=>!clean(b[k])))return json({error:'Completa todos los campos obligatorios.'},422);if(b.consent!==true)return json({error:'Debes autorizar el tratamiento de datos.'},422);if(!/^\S+@\S+\.\S+$/.test(clean(b.email,160)))return json({error:'Correo electrónico inválido.'},422);if(!allowed(b.problem,['medicamento','procedimiento','especialista','continuidad','negacion']))return json({error:'Problema inválido.'},422);const preference=clean(b.preferred_at,40);const slot=preference?new Date(`${preference}:00-05:00`):null;if(slot&&(!Number.isFinite(slot.getTime())||slot.getTime()<Date.now()+1800000))return json({error:'Selecciona una fecha futura válida.'},422);const rid=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(clean(b.request_id,80))?clean(b.request_id,80):crypto.randomUUID();const existing=await env.DB.prepare('SELECT reference FROM consultations WHERE request_id = ?').bind(rid).first();if(existing)return json({reference:existing.reference,name:clean(b.name,120),whatsapp_url:`https://wa.me/573012370047?text=${encodeURIComponent(`Hola, mi referencia es ${existing.reference}`)}`},200);const now=iso(),client=crypto.randomUUID(),consult=crypto.randomUUID(),appointment=crypto.randomUUID(),consent=crypto.randomUUID(),activity=crypto.randomUUID();let reference;try{const year=Number(now.slice(0,4));const counter=await env.DB.prepare('INSERT INTO reference_counters (year,seq) VALUES (?,1) ON CONFLICT(year) DO UPDATE SET seq=seq+1 RETURNING seq').bind(year).first();if(!counter||counter.seq>999999)throw new Error('reference sequence unavailable');reference=`SM-${year}-${String(counter.seq).padStart(6,'0')}`;await env.DB.batch([env.DB.prepare('INSERT INTO clients (id,name,phone,email,address,created_at) VALUES (?,?,?,?,?,?)').bind(client,clean(b.name,120),clean(b.phone,20),clean(b.email,160).toLowerCase(),clean(b.address,180),now),env.DB.prepare('INSERT INTO consultations (id,reference,request_id,client_id,problem,entity_type,has_order,prior_action,urgent,summary,status,priority,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(consult,reference,rid,client,clean(b.problem,40),clean(b.entity,80),clean(b.order,20),clean(b.action,40),'no',clean(b.summary,700),'new','medium',now,now),env.DB.prepare('INSERT INTO consents (id,client_id,consultation_id,policy_version,purpose,granted_at) VALUES (?,?,?,?,?,?)').bind(consent,client,consult,'2026-09-21-v1','Gestionar consulta inicial gratuita y contacto',now),...(slot?[env.DB.prepare('INSERT INTO appointments (id,consultation_id,scheduled_at,timezone,status,professional,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)').bind(appointment,consult,slot.toISOString(),'America/Bogota','requested','Daniel Vergel',now,now)]:[]),env.DB.prepare('INSERT INTO activities (id,consultation_id,actor,action,new_value,created_at) VALUES (?,?,?,?,?,?)').bind(activity,consult,'public','consultation_created',JSON.stringify({reference,appointment_status:slot?'requested':'not_requested'}),now)]);return json({reference,name:clean(b.name,120),whatsapp_url:`https://wa.me/573012370047?text=${encodeURIComponent(`Hola, solicité una consulta gratuita. Mi referencia es ${reference}`)}`},201)}catch(e){if(String(e).includes('UNIQUE')){const prior=await env.DB.prepare('SELECT reference FROM consultations WHERE request_id = ?').bind(rid).first();if(prior)return json({reference:prior.reference,name:clean(b.name,120),whatsapp_url:`https://wa.me/573012370047?text=${encodeURIComponent(`Hola, mi referencia es ${prior.reference}`)}`},200);return json({error:'No fue posible guardar la solicitud. Intenta nuevamente.'},409)}console.error('create consultation failed',e);return json({error:'No fue posible guardar la solicitud. Intenta nuevamente.'},503)}}
async function dashboard(env){const [totals,consultations,appointments]=await env.DB.batch([env.DB.prepare("SELECT count(*) total, sum(status='new') nuevos, sum(status='closed') cerrados FROM consultations"),env.DB.prepare('SELECT c.id,c.reference,c.problem,c.summary,c.status,c.priority,c.created_at,cl.name,cl.phone,cl.email,cl.address,a.id appointment_id,a.scheduled_at,a.status appointment_status FROM consultations c JOIN clients cl ON cl.id=c.client_id LEFT JOIN appointments a ON a.consultation_id=c.id ORDER BY c.created_at DESC LIMIT 100'),env.DB.prepare("SELECT a.id,a.consultation_id,a.scheduled_at,a.status,a.professional,c.reference,cl.name,cl.phone FROM appointments a JOIN consultations c ON c.id=a.consultation_id JOIN clients cl ON cl.id=c.client_id WHERE a.status!='cancelled' ORDER BY a.scheduled_at LIMIT 100")]);return json({stats:totals.results[0]||{},consultations:consultations.results,appointments:appointments.results,timezone:'America/Bogota'})}
async function update(request,env,id){let b;try{b=await request.json()}catch{return json({error:'Solicitud inválida.'},400)}const type=clean(b.type,20),status=clean(b.status,30);if(type==='consultation'){if(!can(request,'write')||!allowed(status,['new','progress','closed']))return json({error:'No autorizado o estado inválido.'},403);const before=await env.DB.prepare('SELECT status FROM consultations WHERE id=?').bind(id).first();if(!before)return json({error:'Registro no encontrado.'},404);const now=iso();await env.DB.batch([env.DB.prepare('UPDATE consultations SET status=?,updated_at=? WHERE id=?').bind(status,now,id),env.DB.prepare('INSERT INTO activities (id,consultation_id,actor,action,previous_value,new_value,created_at) VALUES (?,?,?,?,?,?,?)').bind(crypto.randomUUID(),id,actor(request),'consultation_status_changed',before.status,status,now)]);return json({ok:true})}if(type==='appointment'){
  if(!can(request,'schedule'))return json({error:'No autorizado.'},403);
  const before=await env.DB.prepare('SELECT consultation_id,status,scheduled_at,professional FROM appointments WHERE id=?').bind(id).first();
  if(!before)return json({error:'Registro no encontrado.'},404);
  const transitions={requested:['confirmed','cancelled'],confirmed:['rescheduled','cancelled','attended','no_show'],rescheduled:['confirmed','cancelled']};
  if(!transitions[before.status]?.includes(status))return json({error:'Transición de agenda inválida.'},422);
  const changing=status==='rescheduled';
  const slot=changing?new Date(clean(b.scheduled_at,40)):new Date(before.scheduled_at);
  if(!Number.isFinite(slot.getTime())||(['confirmed','rescheduled'].includes(status)&&slot.getTime()<=Date.now()))return json({error:'Se requiere una fecha futura válida.'},422);
  if(changing&&(!b.scheduled_at||slot.toISOString()===before.scheduled_at))return json({error:'Indica una hora nueva.'},422);
  const professional=clean(b.professional,120)||before.professional;
  if(!professional)return json({error:'Se requiere un profesional.'},422);
  if(['confirmed','rescheduled'].includes(status)){
    const date=new Date(slot.getTime()-5*3600000).toISOString().slice(0,10);
    const available=await env.DB.prepare('SELECT 1 available FROM professional_availability WHERE professional=? AND date=? AND start_at<=? AND end_at>?').bind(professional,date,slot.toISOString(),slot.toISOString()).first();
    if(!available)return json({error:'El profesional no tiene disponibilidad configurada para esa hora.'},409);
  }
  const now=iso();
  try{
    const results=await env.DB.batch([env.DB.prepare('INSERT INTO activities (id,consultation_id,actor,action,previous_value,new_value,created_at) SELECT ?,consultation_id,?,?,?,?,? FROM appointments WHERE id=? AND status=?').bind(crypto.randomUUID(),actor(request),'appointment_status_changed',JSON.stringify({status:before.status,scheduled_at:before.scheduled_at,professional:before.professional}),JSON.stringify({status,scheduled_at:slot.toISOString(),professional}),now,id,before.status),env.DB.prepare('UPDATE appointments SET status=?,scheduled_at=?,professional=?,updated_at=? WHERE id=? AND status=?').bind(status,slot.toISOString(),professional,now,id,before.status)]);
    if(Number(results[1]?.meta?.changes??results[1]?.changes)!==1)return json({error:'La cita cambió; recarga e intenta nuevamente.'},409);
  }catch(e){if(String(e).includes('UNIQUE'))return json({error:'El profesional ya tiene una cita confirmada a esa hora.'},409);throw e}
  return json({ok:true,status,scheduled_at:slot.toISOString(),professional});
}return json({error:'Tipo inválido.'},422)}
export default{async fetch(request,env){const url=new URL(request.url),path=url.pathname;if(request.method==='OPTIONS')return new Response(null,{status:204,headers:{...securityHeaders,'access-control-allow-origin':env.CRM_ORIGIN||'','access-control-allow-headers':'authorization,content-type','access-control-allow-methods':'GET,PATCH,PUT,OPTIONS'}});if(path==='/api/health')return json({ok:true,service:'salvacion-m',time:iso()});if(path==='/api/consultations'&&request.method==='POST')return publicCreate(request,env);if(path==='/api/admin/availability'&&request.method==='GET'){
  if(!admin(request,env)||!can(request,'read'))return json({error:'No autorizado.'},401);
  const date=clean(url.searchParams.get('date'),10),professional=clean(url.searchParams.get('professional'),120);
  if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(Date.parse(date))||!professional)return json({error:'Fecha y profesional obligatorios.'},422);
  const [window,slots]=await Promise.all([env.DB.prepare('SELECT professional,date,start_at,end_at FROM professional_availability WHERE professional=? AND date=?').bind(professional,date).first(),env.DB.prepare("SELECT scheduled_at FROM appointments WHERE professional=? AND status='confirmed' AND scheduled_at>=? AND scheduled_at<? ORDER BY scheduled_at").bind(professional,new Date(Date.parse(date+'T05:00:00Z')).toISOString(),new Date(Date.parse(date+'T05:00:00Z')+86400000).toISOString()).all()]);
  return json({professional,date,timezone:'America/Bogota',window:window||null,confirmed_slots:slots.results});
}
if(path==='/api/admin/availability'&&request.method==='PUT'){
  if(!admin(request,env)||!can(request,'schedule'))return json({error:'No autorizado.'},401);
  let b;try{b=await request.json()}catch{return json({error:'Solicitud inválida.'},400)}
  const professional=clean(b.professional,120),date=clean(b.date,10),start=clean(b.start_at,40),end=clean(b.end_at,40);
  const beginning=new Date(start),ending=new Date(end);
  if(!professional||!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(beginning.getTime())||!Number.isFinite(ending.getTime())||beginning>=ending||beginning<=new Date()||ending-beginning>86400000||new Date(beginning.getTime()-5*3600000).toISOString().slice(0,10)!==date||new Date(ending.getTime()-5*3600000-1).toISOString().slice(0,10)!==date)return json({error:'Ventana de disponibilidad inválida.'},422);
  const existing=await env.DB.prepare("SELECT count(*) n FROM appointments WHERE professional=? AND status='confirmed' AND scheduled_at>=? AND scheduled_at<? AND (scheduled_at<? OR scheduled_at>=?)").bind(professional,new Date(Date.parse(date+'T05:00:00Z')).toISOString(),new Date(Date.parse(date+'T05:00:00Z')+86400000).toISOString(),beginning.toISOString(),ending.toISOString()).first();
  if(existing?.n)return json({error:'Hay citas confirmadas fuera de la nueva ventana.'},409);
  const previous=await env.DB.prepare('SELECT start_at,end_at FROM professional_availability WHERE professional=? AND date=?').bind(professional,date).first();
  const now=iso();await env.DB.batch([env.DB.prepare('INSERT INTO professional_availability (professional,date,start_at,end_at,updated_at) VALUES (?,?,?,?,?) ON CONFLICT(professional,date) DO UPDATE SET start_at=excluded.start_at,end_at=excluded.end_at,updated_at=excluded.updated_at').bind(professional,date,beginning.toISOString(),ending.toISOString(),now),env.DB.prepare('INSERT INTO availability_events (id,professional,date,actor,previous_value,new_value,created_at) VALUES (?,?,?,?,?,?,?)').bind(crypto.randomUUID(),professional,date,actor(request),previous?JSON.stringify(previous):null,JSON.stringify({start_at:beginning.toISOString(),end_at:ending.toISOString()}),now)]);
  return json({ok:true,professional,date,start_at:beginning.toISOString(),end_at:ending.toISOString()});
}
if(path==='/api/admin/dashboard'&&request.method==='GET'){if(!admin(request,env)||!can(request,'read'))return json({error:'No autorizado.'},401);return dashboard(env)}const m=path.match(/^\/api\/admin\/records\/([a-z0-9-]+)$/);if(m&&request.method==='PATCH'){if(!admin(request,env))return json({error:'No autorizado.'},401);return update(request,env,m[1])}if(path.startsWith('/api/'))return json({error:'Ruta no encontrada.'},404);const asset=ASSETS[path]||ASSETS['/'],fresh=['/','/index.html','/styles.css','/app.js'].includes(path);return new Response(asset.body,{headers:{'content-type':asset.type,'cache-control':fresh?'no-cache':'public, max-age=3600',...securityHeaders}})}};
